# file: solution.py
import re

_TOKEN = re.compile(r"\[(-?\d+)\]|([^.\[\]]+)")


def get_path(obj, path, default=None):
    cur = obj
    for m in _TOKEN.finditer(path):
        idx, key = m.groups()
        if idx is not None:
            if not isinstance(cur, list):
                return default
            i = int(idx)
            if not -len(cur) <= i < len(cur):
                return default
            cur = cur[i]
        else:
            if not isinstance(cur, dict) or key not in cur:
                return default
            cur = cur[key]
    return cur
